# Now I will create directories for file_names that do not exist yet in existing_dirs.
for file_name in unique_file_names:
    if file_name not in existing_dirs:
        new_dir_path = base_dir + file_name
        apis.file_system.create_directory(access_token=access_token, directory_path=new_dir_path)

