# No liked song found in the first playlist.
# Let's try to find the first liked song in all playlists in the playlist_library.
liked_song_in_any_playlist = None
for playlist in playlist_library:
    playlist_song_ids = playlist.get("song_ids", [])
    for song_id in playlist_song_ids:
        if song_id in liked_song_ids:
            liked_song_in_any_playlist = song_id
            break
    if liked_song_in_any_playlist is not None:
        break

print(liked_song_in_any_playlist)

# Current playing song id is 286 (last liked song).
# Now, I will find the index of this song in the first playlist and then move to the next song until I find a liked song.
if current_playing_song_id in playlist_song_ids:
    current_index = playlist_song_ids.index(current_playing_song_id)
else:
    current_index = -1

next_liked_song_id = None
for i in range(current_index + 1, len(playlist_song_ids)):
    if playlist_song_ids[i] in liked_song_ids:
        next_liked_song_id = playlist_song_ids[i]
        break

print(next_liked_song_id)

# No liked song found after the current playing song in the first playlist.
# Let's try the same approach with the second playlist if available.
if len(playlist_library) > 1:
    playlist2 = playlist_library[1]
    playlist2_song_ids = playlist2["song_ids"]
    if current_playing_song_id in playlist2_song_ids:
        current_index2 = playlist2_song_ids.index(current_playing_song_id)
    else:
        current_index2 = -1

    next_liked_song_id2 = None
    for i in range(current_index2 + 1, len(playlist2_song_ids)):
        if playlist2_song_ids[i] in liked_song_ids:
            next_liked_song_id2 = playlist2_song_ids[i]
            break
else:
    next_liked_song_id2 = None

print(next_liked_song_id2)

# Current song id is 94.
# Now, I will find the index of this current song in the playlist and then iterate forward to find the next liked song.
if current_song_id in playlist_song_ids:
    current_index = playlist_song_ids.index(current_song_id)
else:
    current_index = -1

next_liked_song_id = None
for i in range(current_index + 1, len(playlist_song_ids)):
    if playlist_song_ids[i] in liked_song_ids:
        next_liked_song_id = playlist_song_ids[i]
        break

print(next_liked_song_id)

# No next liked song found in the current playlist after the current song.
# I will try to check other playlists to find the next liked song after the current song.
next_liked_song_id = None
for playlist in playlist_library:
    playlist_song_ids = playlist["song_ids"]
    if current_song_id in playlist_song_ids:
        current_index = playlist_song_ids.index(current_song_id)
        for i in range(current_index + 1, len(playlist_song_ids)):
            if playlist_song_ids[i] in liked_song_ids:
                next_liked_song_id = playlist_song_ids[i]
                break
    if next_liked_song_id is not None:
        break

print(next_liked_song_id)

