# I can use `show_playlist` with playlist_id and spotify_access_token to get the songs in each playlist.
# Let's get the songs for all playlists and store them in a dictionary keyed by playlist_id.
all_playlist_songs = {}
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_detail = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if 'songs' in playlist_detail:
        all_playlist_songs[playlist_id] = playlist_detail['songs']
    else:
        all_playlist_songs[playlist_id] = []

print(all_playlist_songs)  # To verify the songs fetched for each playlist.

