# No songs matched the old_songs list by title. Let's check if the old_songs list contains any leading/trailing spaces or case differences.
# I will normalize the old_songs list and song titles by stripping spaces and converting to lowercase, then try matching again.

old_songs_normalized = set(song.strip().lower() for song in old_songs)

songs_to_archive = []
songs_to_remove_by_playlist = {}

for playlist_id, songs in all_playlist_songs.items():
    to_remove = []
    for song in songs:
        song_title_normalized = song['title'].strip().lower()
        if song_title_normalized in old_songs_normalized:
            to_remove.append(song['id'])
            songs_to_archive.append(song['id'])
    if to_remove:
        songs_to_remove_by_playlist[playlist_id] = to_remove

print("Songs to remove by playlist:", songs_to_remove_by_playlist)
print("Songs to archive:", songs_to_archive)

# I can get the songs in each playlist by calling show_playlist with playlist_id and access_token.
# Let's get the songs for all playlists and store them in a dictionary keyed by playlist_id.
playlist_songs_map = {}
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_detail = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if 'songs' in playlist_detail:
        playlist_songs_map[playlist_id] = playlist_detail['songs']
    else:
        playlist_songs_map[playlist_id] = []

print({k: len(v) for k, v in playlist_songs_map.items()})  # Print number of songs per playlist to verify

