# The error indicates that playlist_id should be an integer, but it might be a string.
# Let's check the type of playlist_id and convert it to int if needed before calling show_playlist.

archived_song_ids = set()

for playlist in all_playlists:
    playlist_id = playlist.get("id")
    try:
        playlist_id_int = int(playlist_id)
    except Exception:
        continue  # skip if id is not convertible to int

    playlist_details = apis.spotify.show_playlist(playlist_id=playlist_id_int, access_token=spotify_access_token)
    if not playlist_details or "songs" not in playlist_details:
        continue

    songs_in_playlist = playlist_details["songs"]
    songs_to_remove_ids = []

    for song in songs_in_playlist:
        if song["title"] in songs_to_archive:
            songs_to_remove_ids.append(song["id"])
            archived_song_ids.add(song["id"])

    if songs_to_remove_ids:
        apis.spotify.remove_songs_from_playlist(access_token=spotify_access_token, playlist_id=playlist_id_int, song_ids=songs_to_remove_ids)

if archived_song_ids:
    apis.spotify.add_songs_to_playlist(access_token=spotify_access_token, playlist_id=int(old_songs_playlist_id), song_ids=list(archived_song_ids))

apis.supervisor.complete_task()

# Now I will fetch detailed info for each song_id to get the song title and artist(s) for matching.
# The API is spotify.show_song(access_token, song_id).
# I will store song info in a dictionary keyed by song_id.
song_info = {}
for song_id in all_song_ids:
    info = apis.spotify.show_song(access_token=spotify_access_token, song_id=song_id)
    if info:
        song_info[song_id] = info

# Check a few song info entries for verification
print({k: song_info[k] for k in list(song_info)[:3]})

