# The new playlist "Archived Playlist Songs" was created successfully with playlist_id 654.
# Now I will remove the identified old songs from their respective playlists.
# I need to find which playlists contain these old songs and remove them from those playlists.

# First, let's find the mapping of old songs to playlists.
old_song_to_playlists = {}
for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    playlist_songs = playlist.get("songs", [])
    for song in playlist_songs:
        if song["song_id"] in old_song_ids:
            old_song_to_playlists.setdefault(song["song_id"], []).append(playlist_id)

print(old_song_to_playlists)

# The previous code did not find any songs in the playlists because the playlists in all_playlists might not have the "songs" key populated.
# I need to fetch the songs for each playlist individually using the spotify.show_playlist API.

playlist_songs_map = {}
for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    playlist_detail = apis.spotify.show_playlist(access_token=spotify_access_token, playlist_id=playlist_id)
    playlist_songs_map[playlist_id] = playlist_detail.get("songs", [])

# Now, find the mapping of old songs to playlists using the fetched songs.
old_song_to_playlists = {}
for playlist_id, songs in playlist_songs_map.items():
    for song in songs:
        if song["song_id"] in old_song_ids:
            old_song_to_playlists.setdefault(song["song_id"], []).append(playlist_id)

print(old_song_to_playlists)

