# The old_songs_list contains header and bullet points, let's clean it to keep only song lines without the dash and header.
clean_old_songs_list = []
for line in old_songs_list:
    if line.startswith("- "):
        clean_old_songs_list.append(line[2:].strip())

print(clean_old_songs_list)
